caddyfile:
{
    admin off
    persist_config off
    auto_https off
    storage file_system {
        root /tmp/diamond-w8-tls-proxy-k_dmwxh4/caddy-data
    }
    servers {
        protocols h1 h2
    }
}
https://localhost:37899 {
    bind 127.0.0.1
    tls /tmp/diamond-w8-tls-proxy-k_dmwxh4/certificates/localhost.pem /tmp/diamond-w8-tls-proxy-k_dmwxh4/certificates/localhost.key
    reverse_proxy 127.0.0.1:40871 127.0.0.1:44023 {
        lb_policy round_robin
        header_up Host {http.request.host}
        header_up -Forwarded
        header_up -X-Forwarded-*
        health_uri /_diamond/health/ready
        health_headers {
            Host localhost:37899
        }
        health_interval 1s
    }
}
